anthropic_raw_latex:
\begin{proposition}\label{DCedge} 
If $G$ is a mixed graph and $e \in E(G)$, then $$\chi_G(k) = \chi_{G-e}(k) - \chi_{G/e}(k) \, .$$
\end{proposition}

\begin{proposition}\label{DCarc} 
If $G$ is a mixed graph and $a \in A(G)$, then $$\chi_G(k) + \chi_{G_{a}}(k) = \chi_{G-a}(k) + \chi_{G/a}(k) \, .$$
\end{proposition}

\begin{proposition}\label{cycle_contract_lemma}
If $G$ is a strongly connected directed graph, then $\chi_G(k) = k$.
\end{proposition}

\begin{proposition}\label{subcontract}
Let $G$ be a mixed graph and $S$ be a strongly connected directed subgraph of $G$. Then $\chi_G(k)=\chi_{G/S}(k)$. 
\end{proposition}

\begin{prop} 
(Example 3.7 of \cite{bocker1998})
If $T$ is a binary tree such that the interior edges of $T$ are labeled $E=\{e_1,...,e_{n-3}\}$, and $Q$ is a system of quartet trees such that each $q_i \in Q$ distinguishes a unique edge $e_i$ in $T$ with \[|supp(q_i)\backslash \bigcup_{j<i} supp(q_j)|= 1\] for $i=2,...,n-3$, then $Q$ is definitive. 
\label{bocker2}
\end{prop}

